package com.example.statusdrafter.controller; import com.example.statusdrafter.entity.User; import com.example.statusdrafter.service.UserService; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.GetMapping; import org.springframework.web.servlet.view.RedirectView;
@Controller public class HomeController {private final UserService users;public HomeController(UserService u){users=u;} @GetMapping("/") public RedirectView home(Authentication a){User u=users.byUsername(a.getName());return new RedirectView(switch(u.getRole()){case EMPLOYEE->"/employee/dashboard";case MANAGER->"/manager/dashboard";case ADMIN->"/admin/dashboard";});}}
